  currentDir := ""                                                                                                        targetWindow := 0
                                                                                                                          ; 直接获取活动资源管理器窗口句柄
  hwnd := WinActive("ahk_class CabinetWClass")
  if !hwnd
      hwnd := WinActive("ahk_class ExplorerWClass")

  if hwnd {
      try {
          for window in ComObject("Shell.Application").Windows() {
              if (window.HWND = hwnd) {
                  currentDir := window.Document.Folder.Self.Path
                  targetWindow := window
                  break
              }
          }
      }
  }

  currentDir := currentDir = "" ? A_Desktop : currentDir

  ; 生成文件夹名
  folderName := "New Folder"
  basePath := currentDir "\New Folder"

  if FileExist(basePath) {
      counter := 1
      while FileExist(basePath " (" counter ")")
          counter++
      folderName := "New Folder (" counter ")"
  }

  ; 创建文件夹
  DirCreate(currentDir "\" folderName)

  ; 选中
  if IsObject(targetWindow) {
      try targetWindow.Document.SelectItem(targetWindow.Document.Folder.ParseName(folderName), 17)
